/* eslint-disable no-unused-vars */
/* eslint-disable no-undef */
import { Component, h, Prop, Element, ComponentInterface, State, Host, Event, EventEmitter } from '@stencil/core';
import classnames from 'classnames';
import {
  BeforeUploadHook,
  UploadFile,
  UploadChangeParam,
  UploadIconType,
  UploadMaxCountConfig,
  UpLoadSize,
} from '../ks-upload/types';
import { uploadMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { IUploadOption } from '../ks-upload/utils';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import { KsIconPlus, KsIconUpload } from '@fe-infra/keystone-icons-stencil';

const prefix = 'upload-drop';

/**
 * @slot default - Custom drop zone content rendered inside the upload trigger area.
 * @part trigger - The drop zone (trigger) for the uploader.
 */
@Component({
  tag: 'ks-upload-drop',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsUploadDrop implements ComponentInterface {
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Element() el: HTMLKsUploadDropElement;

  /** The size of the upload component, Can be one of the following values: `"sm"` or `"md"`. */
  @Prop() size: UpLoadSize = 'md';

  /** The accepted file types for upload, similar to the HTML `accept` attribute. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() accept: string;
  /** The URL where the files will be uploaded. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() action: string;
  /** Additional data sent with the upload request. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() data: object;
  /** The name attribute value for the files in the upload request, sent to the backend. */
  @Prop() name = 'file';
  /** Disables the upload component, preventing file selection or drag-and-drop functionality. */
  @Prop() @FormContextValueReconcile() disabled = false;
  /** Whether multiple files can be uploaded at once. */
  @Prop() multiple = false;
  /** The headers to be sent along with the upload request. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() headers: object;
  /** The HTTP method used for the upload request. */
  @Prop() method = 'post';
  /** The current list of files in the upload queue. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) fileList?: UploadFile[];
  /** The default file list when the component is first rendered. */
  @Prop() defaultFileList: UploadFile[] = [];
  /** Whether or not to display the uploaded files list. */
  @Prop() showUploadList = true;
  /** A function to be called before the upload process begins, can be used to validate files. */
  @Prop() beforeUpload?: BeforeUploadHook;
  /** The type of icon to display in the upload area. Can be either 'upload' (default) or 'plus'. */
  @Prop() iconType: UploadIconType = 'upload';

  /** Whether to show the instructions text. If set to false, the text part will be hidden. */
  @Prop() showInstructions = true;

  /** Description related to the upload, such as the types of uploads allowed. */
  @Prop() description = '';
  /** The maximum length of the fileList. */
  @Prop() maxCount?: UploadMaxCountConfig;

  /** Allows custom control of the upload process, overriding the default request behavior. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() customRequest: (option: IUploadOption) => void;
  /** A function to be called before a file is removed from the upload queue. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() beforeRemove: (file: UploadFile & { detail: UploadFile }) => boolean | Promise<boolean>;
  /** Custom event emitted when the file list or upload state changes. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Event({ bubbles: false, composed: false }) ksChange: EventEmitter<UploadChangeParam<UploadFile>>;
  /** Custom event emitted when the file upload state errors. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Event({ bubbles: false, composed: false }) ksError: EventEmitter<UploadChangeParam<UploadFile>>;

  @State() highlight = false;

  @State() isError = false;

  private handleChange = (event: CustomEvent<UploadChangeParam<UploadFile>>) => {
    const { error } = event.detail;
    this.highlight = false;
    if (error) {
      this.isError = true;
      this.ksError.emit(event.detail);
    } else {
      this.isError = false;
    }
    this.ksChange.emit?.(event.detail);
  };

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private handleDragOver(e) {
    e.preventDefault();
    this.highlight = true;
  }

  private handleDragLeave() {
    this.highlight = false;
  }

  render() {
    return (
      <Host class="KsUploadDrop">
        <div
          onDragEnter={(e) => this.handleDragOver(e)}
          onDragOver={(e) => this.handleDragOver(e)}
          onDragLeave={() => this.handleDragLeave()}
          data-testid="ks-upload-drag-index-bLkPxb"
        >
          <ks-upload
            size={this.size}
            accept={this.accept}
            action={this.action}
            data={this.data}
            name={this.name}
            disabled={this.disabled}
            multiple={this.multiple}
            headers={this.headers}
            method={this.method}
            fileList={this.fileList}
            defaultFileList={this.defaultFileList}
            showUploadList={this.showUploadList}
            beforeRemove={this.beforeRemove}
            beforeUpload={this.beforeUpload}
            onKsChange={this.handleChange}
            customRequest={this.customRequest}
            onKsError={(event) => {
              this.ksError.emit(event.detail);
            }}
            description={this.description}
            maxCount={this.maxCount}
            data-testid="ks-upload-drag-index-4eqbEm"
          >
            <slot>
              <div
                part="trigger"
                class={classnames(prefix, `${prefix}--plain`, {
                  [`${prefix}--disabled`]: this.disabled,
                  [`${prefix}--highlight`]: this.highlight,
                  [`${prefix}--error`]: this.isError,
                })}
                data-testid="ks-upload-drag-index-8ra1Uc"
              >
                {this.iconType === 'plus' ? (
                  <KsIconPlus class={`${prefix}__icon`} />
                ) : (
                  <KsIconUpload class={`${prefix}__icon`} />
                )}

                {this.showInstructions && (
                  <div class={`${prefix}__text`}>
                    {t(uploadMessages.drop)} <span class={`${prefix}__special-text`}>{t(uploadMessages.click)}</span>
                  </div>
                )}
              </div>
            </slot>
          </ks-upload>
        </div>
      </Host>
    );
  }
}
